private void showReleaseAndReturnButtons()
{
    // If a vehicle has been selected for a new reservation, mark the reservation as ready for pick up
    if(FMRental.Vehicle != 0 && FMRental.State == FMReservationState::New)
    {
        FMRental.State = FmReservationState::ReadyForPickup;
    }
    else if(FMRental.Vehicle == 0 && FMRental.State == FMReservationState::ReadyForPickup)
    {
        FMRental.State = FMReservationState::New;             
    }

    // Show release button if reservation has not already started
    ReleaseVehicleButton.visible(FMRental.State == FMReservationState::ReadyForPickup);
    CompleteRentalButton.visible(FMRental.State == FMReservationState::InProgress);        
}

public void init()
{
    QueryFilter qFilter;
    QueryBuildDataSource qbd;

    super();

    qbd = FMRental_DS.queryBuildDataSource();

    Common record = element.args().record();
    Args args = element.args();

    if(record is FMPickupAndReturnTable)
    {
        FMPickupAndReturnTable cacheRecord = record as FMPickupAndReturnTable;
        qbd.addRange(fieldnum(FMRental, RentalId)).value(cacheRecord.RentalId);
    }

    qFilter = FmRental_DS.query().addQueryFilter(qbd, fieldstr(FMRental, RentalId));
    qFilter = FmRental_DS.query().addQueryFilter(qbd, fieldstr(FMRental, StartDate));
    qFilter = FmRental_DS.query().addQueryFilter(qbd, fieldstr(FMRental, EndDate));
}

public int active()
{
    int ret;

    ret = super();

    element.showReleaseAndReturnButtons();

    return ret;
}

public QueryFilter findOrCreateQueryFilter(
    Query _query,
    QueryBuildDataSource _queryDataSource,
    str _fieldName)
{
    QueryFilter filter;
    int i;

    for(i = 1; i <= _query.queryFilterCount(); i++)
    {
        filter = _query.queryFilter(i);
        if (filter.dataSource().name() == _queryDataSource.name() &&
            filter.field() == _fieldName)
        {
            return filter;
        }
    }

    return _query.addQueryFilter(_queryDataSource, _fieldName);
}

public void setFilterControls()
{
    Query query = fmrental_qr.query(); // Use QueryRun's Query so that the filter can be cleared
    QueryFilter filter;

    filter = this.findOrCreateQueryFilter(
        query,
        query.dataSourceTable(tableNum(FMVehicle)),
        fieldStr(FMVehicle, DisplayRelationType));

    if (filter.value() == '')
    {
        includeTrucks.value(true);
    }
    else
    {
        includeTrucks.value(false);
    }
}

public void updateQuery()
{
    boolean includeTrucksValue = includeTrucks.value();
    QueryFilter filter;
    Query query = fmrental_qr.query(); // Use QueryRun's Query so that the filter can be cleared
    QueryBuildRange range;
    boolean useQueryFilter = true;  // Change to false to see QueryRange on outer join

    if (useQueryFilter)
    {
        filter = this.findOrCreateQueryFilter(
            query,
            query.dataSourceTable(tableNum(FMVehicle)),
            fieldStr(FMVehicle, DisplayRelationType));
        if (includeTrucksValue)
        {
            filter.value('');
        }
        else
        {
            filter.value('!Truck');
        }
    }
    else
    {
        // Optional code to illustrate behavior difference
        // between QueryFilter and QueryRange
        range = SysQuery::findOrCreateRange(
            query.dataSourceTable(tableNum(FMVehicle)),
            fieldNum(FMVehicle, DisplayRelationType));
        if (includeTrucksValue)
        {
            range.value('');
        }
        else
        {
            range.value('!Truck');
        }
    }
}

private void printFilterRange(Query _query)
{
    int i,j;
    QueryFilter filter;
    QueryBuildDataSource qbds;
    QueryBuildRange range;

    for(i = 1; i <= _query.queryFilterCount(); i++)
    {
        filter = _query.queryFilter(i);
        info(strFmt('QueryFilter: DS=%1(%2) Field=%3 Value=%4',
            filter.dataSource().name(),
            tableId2name(filter.dataSource().table()),
            filter.field(),
            filter.value()));
    }

    for(i = 1; i <= _query.dataSourceCount(); i++)
    {
        qbds = _query.dataSourceNo(i);
        for(j = 1; j <= qbds.rangeCount(); j++)
        {
            range = qbds.range(j);
            info(strFmt('QueryRange: DS=%1(%2) Field=%3 Value=%4',
                range.dataSource().name(),
                tableId2name(range.dataSource().table()),
                range.fieldName(),
                range.value()));
        }
    }
}

public void initValue()
{
    FMVehicle   vehicle;
    FMCustomer  customer;            

    super();            

    FMRental.State = FMReservationState::New;

    if (element.args().openMode() == OpenMode::New)
    {
        if (element.args().dataset() == tableNum(FMVehicle))
        {
            vehicle = element.args().record();
            fmRental.Vehicle = vehicle.RecId;
        }
        else if (element.args().dataset() == tableNum(FMCustomer))
        {
            customer = element.args().record();
            fmRental.Customer = customer.RecId;
        }
    }

}

public void clicked()
{
    FMVehicle vehicle;
    FMCustomer customer;

    select customer where customer.RecId == FMRental.Customer;

    select forupdate vehicle where vehicle.RecId == FMRental.Vehicle;
    if(vehicle)
    {
        // If vehicle is not available then do not allow the vehicle to be released
        switch (vehicle.Status)
        {
            case FMVehicleStatus::Rented:
                warning('This vehicle is currently being rented. Please choose an available vehicle.');
                break;

            case FMVehicleStatus::Damaged:
            case FMVehicleStatus::Pending:
            case FMVehicleStatus::Recalled:
            case FMVehicleStatus::InService:
                warning('This vehicle is not available. It may be damaged, in service or recalled. Please choose an available vehicle.');
                break;

            case FMVehicleStatus::Available:

                super();
                break;
        }
    }
    else
    {
        warning("No vehicle assigned");
    }
}

public void clicked()
{            

    FMVehicle vehicle; 

    select vehicle where vehicle.RecId == FMRental.Vehicle;

    // If vehicle is rented then it cannot be returned
    if(vehicle.Status != FMVehicleStatus::Rented)
    {
        warning('This vehicle has already been returned.');
        FMRental.State = FMReservationState::Complete;
        FMRental_DS.research(true);                
    }
    else
    {
        super(); 
    }
}

public boolean modified()
{
    boolean ret;

    ret = super();

    if (ret == true)
    {
        fmrental_ds.updateQuery();
        fmrental_ds.research(true);
    }

    return ret;
}
